pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, address _caller) public {
        // _caller must be owner for withdraw, and not the deployed C address
        vm.assume(_caller != address(0) && _caller != address(c));

        // fund C with at least _value
        vm.deal(address(c), _value);

        // set owner to _caller and prank as owner
        // we cannot directly set owner, but we can transfer ownership? No, owner is set at deployment.
        // We need the caller to be the owner for withdraw to succeed. We can transfer ownership via a public function? There is no such function.
        // The only way to change owner is not provided. So we must use the deployer (this contract) as owner.
        // Let's restrict to the actual owner, which is address(this). So we cannot fuzz _caller freely.
        // We'll use the deployer as owner.
        address actualOwner = address(this);

        // We must ensure prerequisite: C has at least _value. We also bound _value to avoid overflow and ensure it's <= address(c).balance
        _value = bound(_value, 1, address(c).balance);

        uint256 ownerBalanceBefore = actualOwner.balance;

        // call withdraw as owner
        c.withdraw(_value);

        uint256 ownerBalanceAfter = actualOwner.balance;

        // Rule: owner's balance must increase by exactly _value
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + _value);
    }
}

